#include <iostream>
#include <queue>
#include <map>
using namespace std;
typedef map<int,int> mi;

mi edge[7000];
char buf[20][20];
int n,m,vn,from[7000],flow[7000],tox[10][10];

inline int aug(int s,int t,int cap){
  int result=0;
  for (int aug=1; aug--;){
    for (int i=vn; i--;) from[i]=-1;
    from[s]=s;
    flow[s]=cap;
    queue<int> bfs;
    for (bfs.push(s); not bfs.empty(); bfs.pop()){
      int x=bfs.front();
      if (x==t){
        for (aug=1; x!=s; x=from[x])
          edge[from[x]][x]-=flow[t],
          edge[x][from[x]]+=flow[t];
        result+=flow[t];
        break;
      }
      for (mi::iterator e=edge[x].begin(); e!=edge[x].end(); e++)
        if (e->second>=cap and !~from[e->first])
          from[e->first]=x, flow[e->first]=min(e->second,flow[x]), bfs.push(e->first);
    }
  }
  return result;
}

inline int enc(int x,int y,int t){
  return x+y*n+t*n*n+2;
}

int main(){
  ios::sync_with_stdio(0);
  cin>>n>>m;

  int res=0;
  for (int i=0; i<n; i++)
    for (int j=!(cin>>buf[i]); j<n; j++)
      if (buf[i][j]>'0' and buf[i][j]<='9') edge[0][enc(i,j,0)]=buf[i][j]-'0';
  for (int i=0; i<n; i++) cin>>buf[i];

  static int const dx[]={-1,0,1,0};
  static int const dy[]={0,-1,0,1};

  queue<pair<int,int>> bfs;
  for (int i=n; i--;)
    for (int j=n; j--;){
      if (buf[i][j]=='Z') tox[i][j]=0, bfs.emplace(i,j);
      else tox[i][j]=m+1;
    }

  for (; not bfs.empty(); bfs.pop()){
    for (int i=4; i--;){
      int t=tox[bfs.front().first][bfs.front().second];
      int x=bfs.front().first+dx[i];
      int y=bfs.front().second+dy[i];
      if (x>=0 and y>=0 and x<n and y<n and buf[x][y]!='Y' and t+1<tox[x][y]){
        tox[x][y]=t+1;
        bfs.emplace(x,y);
      }
    }
  }

  vn=enc(n-1,n-1,m)+1;

  for (int i=n; i--;)
    for (int j=n; j--;){
      for (int t=0; t<m; t++){
        if (t<m) for (int q=4; q--;){
          int x=i+dx[q];
          int y=j+dy[q];
          if (x>=0 and y>=0 and x<n and y<n and buf[x][y]!='Y' and t+1<tox[x][y]+(buf[x][y]>'0' and buf[x][y]<='9') and t<tox[i][j]){
            edge[enc(i,j,t)][enc(x,y,t+1)]=1000;
          }
        }
        if (buf[i][j]>'0' and buf[i][j]<='9'){
          edge[enc(i,j,t)][enc(i,j,m)]=buf[i][j]-'0';
        }
      }
      if (buf[i][j]>'0' and buf[i][j]<='9'){
        edge[enc(i,j,m)][1]=buf[i][j]-'0';
      }
    }

  for (int u=8; u; u/=2) res+=aug(0,1,u);
  cout<<res<<'\n';
}


